package com.astrocare.controller; import com.astrocare.dto.*; import com.astrocare.service.EmergencyService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/emergency") @RequiredArgsConstructor public class EmergencyController {private final EmergencyService service; @PostMapping("/sos") @PreAuthorize("hasRole('ASTRONAUT')") public EmergencyResponse sos(@Valid @RequestBody SosRequest r,Authentication a){return service.sos(r,a.getName());}}
